from pathlib import Path
import json
wanted = {'CATALOGUE-COMMISSIONED-REVIEW-LIVE-TEST', 'CATALOGUE-PAYHIP-DECISION', 'WELFARE-LIVE-DEMAND', 'WELFARE-SITE-RETIRE', 'TEXT-CSV-INTAKE-EXPERIMENT'}
digest = 'b5192231bdfa03f011ea45273891c67b883b7c0a4f4d2bef75f7b22e684aa711'
def records(value):
    if isinstance(value, dict):
        yield value
        for child in value.values():
            yield from records(child)
    elif isinstance(value, list):
        for child in value:
            yield from records(child)
for path in sorted(Path('world/pages').glob('*.json')):
    if not path.name.startswith(('missions-', 'reviews-')):
        continue
    for row in records(json.loads(path.read_text())):
        if row.get('mission_id') in wanted and 'status' in row:
            print(json.dumps({k: row.get(k) for k in ('mission_id','status','agent_id','lease_expires_at','evidence')}))
        if row.get('digest') == digest and row.get('subject') == 'site:shopify-catalogue-example':
            print(json.dumps({k: row.get(k) for k in ('subject','digest','verdict','host_provider','seq','notes')}))
print('Invoice checkpoint files:', [p.name for p in sorted(Path('products/distribution/invoice-checkpoint').glob('*.json'))])
